\title{The Scalar Logarithmic Radius on the Vertical Line $1+ti$:\\
Uniqueness, a Certified Rational Interval, and Unitary Lifts}
\author{Aristotle}
\date{9 August 2026}

\begin{document}
\maketitle

\begin{abstract}
We study the \emph{scalar logarithmic radius} $R(t)=\ab{\Log(1+ti)}$, $t\in\RR$, where $\Log$ is the principal branch of the complex logarithm. We prove the closed form
\[
R(t)^{2}=\Bigl(\tfrac12\log(1+t^{2})\Bigr)^{2}+(\arctan t)^{2},
\]
and deduce that $R$ is strictly increasing, hence injective, on $[0,\infty)$. Combined with continuity and the explicit growth estimate $R(e^{r})\ge r$, this shows that $R$ restricts to a bijection of $[0,\infty)$ onto itself: every radius is attained exactly once. In particular $R(t)=1$ has a unique positive solution $t^{\star}$, upgrading an earlier existence-only statement to uniqueness. We then certify $t^{\star}\in[6/5,5/4]$, a thirty-fold reduction in width over the previously available interval $[1/2,3]$, using only the tangent-line bounds $1-x^{-1}\le\log x\le x-1$ applied after splitting off a factor of $2$, the two-sided bound $y/(1+y^{2})\le\arctan y\le y$, and the exact addition identities $\arctan\frac65=\frac\pi4+\arctan\frac1{11}$ and $\arctan\frac54=\frac\pi4+\arctan\frac19$. Finally we develop the operator-algebraic consequences: a unimodular scalar times the unit of a complex $*$-algebra is unitary, so the certified root yields a unitary scalar in every matrix $C^{\star}$-algebra, and the polar normalization $\Log(1+ti)/R(t)$ is unitary for every $t\neq0$; every unitary with finite spectrum in a unital $C^{\star}$-algebra equals $\exp(ix)$ for a self-adjoint $x$, so every unitary matrix is $\exp(iH)$ with $H$ Hermitian; every unitary matrix factors as a unimodular scalar times a determinant-one unitary; and for every $t\neq0$ the scalar factor $\Log(1+ti)I_{2}$ is unitary but never special unitary.
\end{abstract}

\noindent\textbf{Keywords.} Principal complex logarithm; arctangent addition identities; certified interval arithmetic; strict monotonicity; unitary group; $C^{\star}$-algebra; exponential surjectivity; special unitary group.

\section{Introduction}

\subsection{The problem}
Fix the vertical line $L=\{1+ti:t\in\RR\}$ in the complex plane and apply the principal logarithm. Since $L$ lies strictly in the right half-plane, $\Log$ is holomorphic near $L$ and $\Log(L)$ is a real-analytic curve through the origin. We ask where that curve meets circles centred at the origin, and above all where it meets the \emph{unit} circle:
\begin{equation}\label{eq:main}
\ab{\Log(1+ti)}=1 .
\end{equation}
Equation \eqref{eq:main} is transcendental in an essential way: it couples $\log$ and $\arctan$ with no algebraic relation between them, and admits no closed-form solution. What one can do --- and what we do here --- is prove that its solution set is exactly $\{-t^{\star},t^{\star}\}$ for a single positive constant, and confine $t^{\star}$ to a narrow interval with rational endpoints by a self-contained certificate.

\subsection{Motivation}
A complex number of modulus $1$ is precisely a unitary element of the one-dimensional $C^{\star}$-algebra $\CC$, and multiplying the unit of any complex $*$-algebra by such a scalar produces a unitary element --- a \emph{global phase}. Equation \eqref{eq:main} therefore asks: for which shift parameters $t$ is the logarithm of $1+ti$ itself a legitimate phase? The map $x\mapsto\log(1+x)$ is the canonical multiplicative-to-additive nonlinearity, and the imaginary shift $x=ti$ is what appears when the underlying signal is a phase rather than an amplitude; \eqref{eq:main} is the calibration equation for such a nonlinearity.

\subsection{Contributions}
\begin{enumerate}
\item A closed form for $R(t)^{2}$ (Theorem~\ref{thm:closed}) reducing the problem to a two-term real equation.
\item Strict monotonicity of $R$ on $[0,\infty)$ (Theorem~\ref{thm:monoR}), hence injectivity, hence uniqueness of the positive root (Theorem~\ref{thm:unique}).
\item A certified rational interval $[6/5,5/4]$ for $t^{\star}$ (Theorem~\ref{thm:ivt}, Corollary~\ref{cor:loc}), improving $[1/2,3]$ by a factor of $30$ in width.
\item A bijectivity theorem (Theorem~\ref{thm:bij}): every circle is hit exactly once.
\item Unitary lifts (Theorems~\ref{thm:scalarunit} and \ref{thm:polar}).
\item Exponential surjectivity (Theorem~\ref{thm:expsurj}, Corollary~\ref{cor:matexp}).
\item Determinant splitting and an $SU(2)$ obstruction (Theorems~\ref{thm:detsplit} and \ref{thm:obstruction}).
\end{enumerate}

\section{Notation and conventions}

Throughout, $\Log:\CC\setminus(-\infty,0]\to\CC$ is the principal branch,
\[
\Log z=\log\ab{z}+i\Arg z,\qquad \Arg z\in(-\pi,\pi],
\]
with $\log$ the real natural logarithm. For a unital complex $*$-algebra $A$ we write $\mathcal U(A)=\{u\in A: u^{*}u=uu^{*}=1\}$, $\sped(u)$ for the spectrum, and call $x$ self-adjoint if $x^{*}=x$. For matrices $M^{*}$ is the conjugate transpose, $\Herm(n)$ the Hermitian matrices, $U(n)=\mathcal U(M_{n}(\CC))$ and $SU(n)=\{U\in U(n):\det U=1\}$.

\begin{definition}[Scalar logarithmic radius]
For $t\in\RR$ set $R(t):=\ab{\Log(1+ti)}$.
\end{definition}

\begin{definition}[Radius square]
For $t\in\RR$ set
$\displaystyle S(t):=\Bigl(\frac{\log(1+t^{2})}{2}\Bigr)^{2}+(\arctan t)^{2}.$
\end{definition}

\begin{definition}[Polar normalization]
For $w\in\CC\setminus\{0\}$ set $\pu(w):=\ab{w}^{-1}w$.
\end{definition}

Since $1+ti$ lies in the open right half-plane for every real $t$, it is in the domain of $\Log$ and $R$ is everywhere defined and finite.

\section{The closed form}

\begin{lemma}[Modulus and argument]\label{lem:modarg}
For every $t\in\RR$, $\ab{1+ti}=\sqrt{1+t^{2}}$ and $\Arg(1+ti)=\arctan t$.
\end{lemma}

\begin{proof}
The modulus is immediate. Since the real part $1$ is positive, the principal argument on the right half-plane is $\Arg(a+bi)=\arcsin\bigl(b/\ab{a+bi}\bigr)$, and $\arcsin\bigl(t/\sqrt{1+t^{2}}\bigr)=\arctan t$, which is the standard identity obtained from $\sin(\arctan t)=t/\sqrt{1+t^{2}}$.
\end{proof}

\begin{theorem}[Closed form]\label{thm:closed}
For every $t\in\RR$,
\[
R(t)^{2}=S(t)=\Bigl(\frac{\log(1+t^{2})}{2}\Bigr)^{2}+(\arctan t)^{2}.
\]
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:modarg}, $\operatorname{Re}\Log(1+ti)=\log\sqrt{1+t^{2}}=\tfrac12\log(1+t^{2})$ and $\operatorname{Im}\Log(1+ti)=\arctan t$. Now $\ab{w}^{2}=(\operatorname{Re}w)^{2}+(\operatorname{Im}w)^{2}$.
\end{proof}

\begin{corollary}[Basic properties]\label{cor:basic}
$R\ge0$, $S\ge0$, $R=\sqrt{S}$, $R(0)=0$, and $R$ is even: $R(-t)=R(t)$.
\end{corollary}

\begin{proof}
Nonnegativity is clear and $S=R^{2}$, so $R=\sqrt{S}$. At $t=0$, $\Log 1=0$. Evenness holds because $t\mapsto t^{2}$ is even and $\arctan$ is odd, so its square is even.
\end{proof}

Corollary~\ref{cor:basic} contains the symmetry statement: every positive solution of $R(t)=r$ is matched by the negative solution $-t$.

\begin{lemma}[Continuity]\label{lem:cont}
$R$ is continuous on $\RR$.
\end{lemma}

\begin{proof}
$t\mapsto 1+ti$ is continuous with values in the open right half-plane, contained in the slit plane where $\Log$ is continuous; the modulus is continuous.
\end{proof}

\section{Strict monotonicity and uniqueness}

\begin{lemma}\label{lem:nonneg}
For $t\ge0$, $\log(1+t^{2})\ge0$ and $\arctan t\ge0$.
\end{lemma}

\begin{theorem}[Strict monotonicity of $S$]\label{thm:monoS}
$S$ is strictly increasing on $[0,\infty)$.
\end{theorem}

\begin{proof}
Let $0\le a<b$. Then $1+a^{2}<1+b^{2}$, so $0\le\log(1+a^{2})<\log(1+b^{2})$; and $0\le\arctan a<\arctan b$ by strict monotonicity of $\arctan$ and Lemma~\ref{lem:nonneg}. Squaring is strictly increasing on $[0,\infty)$, so both summands of $S$ strictly increase.
\end{proof}

\begin{theorem}[Strict monotonicity of $R$]\label{thm:monoR}
$R$ is strictly increasing on $[0,\infty)$; in particular $R$ is injective there.
\end{theorem}

\begin{proof}
$R=\sqrt{S}$ with $S\ge0$ strictly increasing on $[0,\infty)$ by Theorem~\ref{thm:monoS}, and $\sqrt{\cdot}$ is strictly increasing on $[0,\infty)$.
\end{proof}

\begin{theorem}[Existence and uniqueness]\label{thm:unique}
There is exactly one $t>0$ with $R(t)=1$; we denote it $t^{\star}$.
\end{theorem}

\begin{proof}
Uniqueness is injectivity (Theorem~\ref{thm:monoR}). Existence follows from Lemma~\ref{lem:cont}, Theorem~\ref{thm:upper} and Theorem~\ref{thm:lower} below by the intermediate value theorem on $[6/5,5/4]$.
\end{proof}

\section{The certified interval $[6/5,5/4]$}

The true values are $S(6/5)=0.966393\ldots$ and $S(5/4)=1.024278\ldots$, so each of the four estimates below must be accurate to a few percent.

\subsection{Elementary tools}

\begin{lemma}[Upper arctangent bound]\label{lem:atanup}
For $y\ge0$, $\arctan y\le y$.
\end{lemma}

\begin{proof}
Let $x=\arctan y\in[0,\pi/2)$. The tangent inequality gives $x\le\tan x$ on $[0,\pi/2)$, and $\tan x=y$.
\end{proof}

\begin{lemma}[Lower arctangent bound]\label{lem:atanlow}
For $y\ge0$, $\dfrac{y}{1+y^{2}}\le\arctan y$.
\end{lemma}

\begin{proof}
Put $x=\arctan y\ge0$, so $\sin x=y/\sqrt{1+y^{2}}$ and $\cos x=1/\sqrt{1+y^{2}}$, whence $\sin(2x)=2\sin x\cos x=2y/(1+y^{2})$. Since $\sin u\le u$ for $u\ge0$, we get $2y/(1+y^{2})\le 2x=2\arctan y$.
\end{proof}

The two bounds bracket $\arctan y$ within $y^{3}/(1+y^{2})$, which is about $1.4\times10^{-3}$ at $y=1/9$. This is why the following identities matter: they move the evaluation point into the region where the bracket is negligible.

\begin{lemma}[Exact addition identities]\label{lem:addid}
$\arctan\frac65=\frac{\pi}{4}+\arctan\frac1{11}$ and $\arctan\frac54=\frac{\pi}{4}+\arctan\frac19$.
\end{lemma}

\begin{proof}
For $xy<1$ one has $\arctan x+\arctan y=\arctan\frac{x+y}{1-xy}$. Taking $x=1$ (so $\arctan x=\pi/4$) and $y<1$ gives $\frac{\pi}{4}+\arctan y=\arctan\frac{1+y}{1-y}$. With $y=1/11$ the argument is $\frac{12/11}{10/11}=\frac65$; with $y=1/9$ it is $\frac{10/9}{8/9}=\frac54$.
\end{proof}

We also use the tangent-line bounds
\begin{equation}\label{eq:logbd}
1-\frac1x\;\le\;\log x\;\le\;x-1\qquad(x>0)
\end{equation}
and the certified numerical bounds
\begin{equation}\label{eq:consts}
0.6931471803<\log 2<0.6931471808,\qquad 3.141592<\pi<3.15 .
\end{equation}

\subsection{The two endpoint estimates}

\begin{theorem}\label{thm:upper}
$S(6/5)<1$, hence $R(6/5)<1$.
\end{theorem}

\begin{proof}
Let $L=\log\bigl(1+(6/5)^{2}\bigr)=\log\frac{61}{25}$. Split off a factor of two: $\frac{61}{25}=2\cdot\frac{61}{50}$, so $L=\log2+\log\frac{61}{50}$. By \eqref{eq:logbd}, $\log\frac{61}{50}\le\frac{11}{50}=0.22$, and $\log2<0.6931471808$ by \eqref{eq:consts}; hence $0\le L\le0.9131472$ and $(L/2)^{2}\le0.208465$. By Lemmas~\ref{lem:addid} and \ref{lem:atanup},
\[
\arctan\tfrac65=\tfrac\pi4+\arctan\tfrac1{11}\le\tfrac{3.15}{4}+\tfrac1{11}=0.87841\ldots\le0.8785 ,
\]
so $(\arctan\frac65)^{2}\le0.771763$. Adding, $S(6/5)\le0.980228<1$, and $R(6/5)=\sqrt{S(6/5)}<1$.
\end{proof}

\begin{theorem}\label{thm:lower}
$S(5/4)>1$, hence $R(5/4)>1$.
\end{theorem}

\begin{proof}
Let $L=\log\bigl(1+(5/4)^{2}\bigr)=\log\frac{41}{16}$ and write $\frac{41}{16}=2\cdot\frac{41}{32}$, so $L=\log2+\log\frac{41}{32}$. The lower bound in \eqref{eq:logbd} gives $\log\frac{41}{32}\ge1-\frac{32}{41}=\frac{9}{41}=0.2195121\ldots$, and $\log2>0.6931471803$; hence $L\ge0.9126593$ and $(L/2)^{2}\ge0.208236$. By Lemmas~\ref{lem:addid} and \ref{lem:atanlow},
\[
\arctan\tfrac54=\tfrac\pi4+\arctan\tfrac19\ge\tfrac{3.141592}{4}+\frac{1/9}{1+1/81}=0.785398+\tfrac{9}{82}=0.895154\ldots\ge 0.8951,
\]
so $(\arctan\frac54)^{2}\ge0.801204$. Adding, $S(5/4)\ge1.009440>1$.
\end{proof}

\begin{theorem}[Certified interval: existence]\label{thm:ivt}
There exists $t\in[6/5,5/4]$ with $R(t)=1$.
\end{theorem}

\begin{proof}
$R$ is continuous (Lemma~\ref{lem:cont}) with $R(6/5)<1<R(5/4)$ by Theorems~\ref{thm:upper} and \ref{thm:lower}; apply the intermediate value theorem.
\end{proof}

\begin{corollary}[Certified interval: localization]\label{cor:loc}
If $t>0$ and $R(t)=1$ then $t\in[6/5,5/4]$. In particular $t^{\star}\in[6/5,5/4]$.
\end{corollary}

\begin{proof}
If $t<6/5$ then $1=R(t)<R(6/5)<1$ by Theorem~\ref{thm:monoR}, absurd; if $t>5/4$ then $1<R(5/4)<R(t)=1$, absurd.
\end{proof}

\begin{remark}
The previous certificate $[1/2,3]$ has width $5/2$; the new one has width $1/20$, a factor-of-$30$ improvement. Numerically $t^{\star}=1.2290375625139\ldots$, comfortably interior.
\end{remark}

\section{Every circle is hit exactly once}

\begin{lemma}[Growth]\label{lem:growth}
For every $r\in\RR$, $R(e^{r})\ge r$.
\end{lemma}

\begin{proof}
For $r\le0$ this is trivial since $R\ge0$. For $r>0$, discard the arctangent term: $S(e^{r})\ge\bigl(\tfrac12\log(1+e^{2r})\bigr)^{2}$, and $\log(1+e^{2r})\ge\log e^{2r}=2r$, so $R(e^{r})=\sqrt{S(e^{r})}\ge\tfrac12\log(1+e^{2r})\ge r$.
\end{proof}

\begin{theorem}[The radius map is a bijection]\label{thm:bij}
For every $r\ge0$ there is exactly one $t\ge0$ with $R(t)=r$. Thus $R|_{[0,\infty)}:[0,\infty)\to[0,\infty)$ is a strictly increasing continuous bijection, hence an increasing homeomorphism.
\end{theorem}

\begin{proof}
Existence: $R(0)=0\le r\le R(e^{r})$ by Lemma~\ref{lem:growth}, so the intermediate value theorem on $[0,e^{r}]$ gives a root. Uniqueness: Theorem~\ref{thm:monoR}. A continuous strictly monotone bijection between intervals is a homeomorphism.
\end{proof}

\begin{corollary}
For $r>0$, $\{t\in\RR:R(t)=r\}=\{-t_{r},t_{r}\}$ with $t_{r}>0$ the unique nonnegative solution. In particular the solution set of \eqref{eq:main} is $\{\pm t^{\star}\}$.
\end{corollary}

\section{Unitary lifts of the scalar factor}

Let $A$ be a unital complex $*$-algebra, i.e.\ a unital $\CC$-algebra with an involution satisfying $(\lambda a)^{*}=\bar\lambda a^{*}$. Matrix algebras with conjugate transpose are the model case.

\begin{theorem}[Unimodular scalars are unitary]\label{thm:scalarunit}
If $z\in\CC$ with $\ab{z}=1$, then $z\cdot1_{A}\in\mathcal U(A)$.
\end{theorem}

\begin{proof}
$\bar zz=z\bar z=\ab{z}^{2}=1$, so $(z1)^{*}(z1)=\bar z z\cdot 1=1$ and $(z1)(z1)^{*}=z\bar z\cdot1=1$.
\end{proof}

\begin{corollary}[Matrix lift of the certified root]
For every $n$ there is $t\in[6/5,5/4]$ with $\Log(1+ti)\,I_{n}\in\mathcal U(M_{n}(\CC))$.
\end{corollary}

\begin{proof}
Take $t=t^{\star}$, which lies in $[6/5,5/4]$ by Corollary~\ref{cor:loc} and satisfies $\ab{\Log(1+t^{\star}i)}=1$; apply Theorem~\ref{thm:scalarunit}.
\end{proof}

\begin{lemma}\label{lem:nonvanish}
For $t\neq0$, $\Log(1+ti)\neq0$.
\end{lemma}

\begin{proof}
Its real part is $\tfrac12\log(1+t^{2})>0$ because $1+t^{2}>1$.
\end{proof}

\begin{theorem}[Polar-normalized factor is always unitary]\label{thm:polar}
For every $t\neq0$ and every unital complex $*$-algebra $A$,
\[
\pu\bigl(\Log(1+ti)\bigr)\,1_{A}=\frac{\Log(1+ti)}{\ab{\Log(1+ti)}}\,1_{A}\in\mathcal U(A).
\]
\end{theorem}

\begin{proof}
The denominator is nonzero by Lemma~\ref{lem:nonvanish}, and $\ab{\ab{w}^{-1}w}=1$; apply Theorem~\ref{thm:scalarunit}.
\end{proof}

\begin{proposition}[Consistency at the root]
If $R(t)=1$ then $\pu\bigl(\Log(1+ti)\bigr)=\Log(1+ti)$: the polar normalization is invisible exactly at the certified root.
\end{proposition}

As $t$ ranges over $(0,\infty)$ the argument of the normalized family is $\arctan\bigl(\arctan t\,\big/\,\tfrac12\log(1+t^{2})\bigr)$, which tends to $\pi/2$ as $t\to0^{+}$ and to $0$ as $t\to\infty$; the family therefore sweeps the open first-quadrant arc of the unit circle.

\section{Exponential surjectivity onto unitaries}

The standard construction of a logarithm of a unitary uses the principal branch, which is discontinuous at $-1$ and therefore requires $-1\notin\sped(u)$, equivalently $\|u-1\|<2$. A general unitary may have $-1$ in its spectrum; the remedy is to rotate.

\begin{lemma}[A finite set cannot cover the circle]\label{lem:circle}
Let $S\subseteq\CC$ be finite. Then there is $\theta\in\RR$ with $-e^{i\theta}\notin S$.
\end{lemma}

\begin{proof}
Otherwise $f(\theta)=-e^{i\theta}$ maps $[0,2\pi)$ into $S$. But $f$ is injective on $[0,2\pi)$, since $e^{ia}=e^{ib}$ forces $a-b\in2\pi\ZZ$ and the only such difference of absolute value $<2\pi$ is $0$; so $f([0,2\pi))$ is infinite, contradicting finiteness of $S$.
\end{proof}

\begin{lemma}[Rotation moves the spectrum]\label{lem:rot}
Let $A$ be a unital $C^{\star}$-algebra, $u\in\mathcal U(A)$, and $\theta\in\RR$ with $-e^{i\theta}\notin\sped(u)$. Put $c=e^{-i\theta}$. Then $cu\in\mathcal U(A)$, $-1\notin\sped(cu)$, and $\|cu-1\|<2$.
\end{lemma}

\begin{proof}
$c1$ is unitary by Theorem~\ref{thm:scalarunit}, so $cu=(c1)u$ is unitary. Since $\sped(cu)=c\,\sped(u)$, if $-1=cz$ with $z\in\sped(u)$ then multiplying by $e^{i\theta}$ and using $ce^{i\theta}=1$ gives $z=-e^{i\theta}\in\sped(u)$, a contradiction. Finally, for a unitary $v$ one has $\|v-1\|=\sup\{\ab{z-1}:z\in\sped(v)\}$ by normality, and on the unit circle $\ab{z-1}=2$ only at $z=-1$; hence $\|v-1\|<2$.
\end{proof}

\begin{theorem}[Exponential surjectivity, finite spectrum]\label{thm:expsurj}
Let $A$ be a unital $C^{\star}$-algebra and $u\in\mathcal U(A)$ with $\sped(u)$ finite. Then there is a self-adjoint $x\in A$ with $\exp(ix)=u$.
\end{theorem}

\begin{proof}
Assume $A\neq0$. By Lemma~\ref{lem:circle} choose $\theta$ with $-e^{i\theta}\notin\sped(u)$, put $c=e^{-i\theta}$ and $v=cu$. By Lemma~\ref{lem:rot}, $v$ is unitary with $\|v-1\|<2$, so the principal logarithm is continuous on a neighbourhood of $\sped(v)$ in the circle, and the continuous functional calculus yields a self-adjoint $x_{0}\in A$ (the argument of $v$, with spectrum in $(-\pi,\pi)$) with $\exp(ix_{0})=v=cu$. Set $x:=\theta1_{A}+x_{0}$, which is self-adjoint since $\theta$ is real. As $i\theta1$ is central it commutes with $ix_{0}$, so
\[
\exp(ix)=\exp(i\theta1)\exp(ix_{0})=\bigl(e^{i\theta}1\bigr)(cu)=\bigl(e^{i\theta}c\bigr)u=u . \qedhere
\]
\end{proof}

\begin{corollary}[Every unitary matrix is $\exp(iH)$]\label{cor:matexp}
For every $n$ and every $U\in U(n)$ there is $H\in\Herm(n)$ with $\exp(iH)=U$.
\end{corollary}

\begin{proof}
$M_{n}(\CC)$ with the operator norm is a unital $C^{\star}$-algebra and the spectrum of a matrix is its finite eigenvalue set; apply Theorem~\ref{thm:expsurj}.
\end{proof}

\begin{remark}
Finiteness of the spectrum is used only through Lemma~\ref{lem:circle}; the same proof gives exponential surjectivity for every unitary whose spectrum omits at least one point of the circle.
\end{remark}

\section{Determinant tracking and the $SU(2)$ obstruction}

\begin{lemma}\label{lem:detmod}
If $U\in U(n)$ then $\ab{\det U}=1$.
\end{lemma}

\begin{proof}
Taking determinants in $U^{*}U=I$ gives $\overline{\det U}\det U=1$, i.e.\ $\ab{\det U}^{2}=1$.
\end{proof}

\begin{theorem}[Scalar times special unitary]\label{thm:detsplit}
Let $n\ge1$ and $U\in U(n)$. There exist $z\in\CC$ with $\ab z=1$ and $V\in U(n)$ with $\det V=1$ such that $U=zV$.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:detmod}, $\det U=e^{i\alpha}$ with $\alpha=\Arg(\det U)$. Put $z=e^{i\alpha/n}$ and $V=z^{-1}U$. Then $\ab z=1$, $z^{n}=\det U$, $V$ is unitary as the product of the unitary $z^{-1}I$ with $U$, and $\det V=z^{-n}\det U=1$; finally $zV=U$.
\end{proof}

\begin{theorem}[$SU(2)$ obstruction]\label{thm:obstruction}
For every real $t\neq0$, $\det\bigl(\Log(1+ti)I_{2}\bigr)\neq1$; equivalently $\Log(1+ti)I_{2}\notin SU(2)$, unitary though it may be.
\end{theorem}

\begin{proof}
Write $z=\Log(1+ti)$, so $\operatorname{Im}z=\arctan t\neq0$. In dimension $2$, $\det(zI_{2})=z^{2}$; if $z^{2}=1$ then $(z-1)(z+1)=0$, so $z=\pm1$ is real, a contradiction.
\end{proof}

Thus the special unitary content of a gate must come from the determinant-one factor of Theorem~\ref{thm:detsplit}, never from the scalar. This is the correct conclusion rather than a defect: global phase is physically unobservable, and the theorem quantifies exactly that.

\section{Algorithms}

\paragraph{Certified bisection.} Since $R$ is continuous and strictly increasing with $R(6/5)<1<R(5/4)$, bisection on $[6/5,5/4]$ converges to $t^{\star}$ with error at most $2^{-k}/20$ after $k$ steps; monotonicity rules out spurious brackets. In exact rational arithmetic with certified enclosures of $\log$ and $\arctan$, each step yields a proved interval, and $50$ steps give roughly $16$ correct digits. Complexity: $O(k)$ evaluations, linear convergence with rate $1/2$.

\paragraph{Newton refinement.} $S$ is smooth with
\[
S'(t)=\frac{t\log(1+t^{2})+2\arctan t}{1+t^{2}}>0\quad(t>0),
\]
so Newton's method on $S(t)-1$ converges quadratically from any start in $[6/5,5/4]$; six iterations from $t_{0}=1.2$ reach machine precision.

\paragraph{Hermitian generator.} Corollary~\ref{cor:matexp} is constructive via the spectral theorem: diagonalise $U=W\operatorname{diag}(e^{i\phi_{1}},\dots,e^{i\phi_{n}})W^{*}$ with $\phi_{j}\in(-\pi,\pi]$ and set $H=W\operatorname{diag}(\phi_{1},\dots,\phi_{n})W^{*}$. The rotation trick corresponds to the freedom of shifting all $\phi_{j}$ by a common $\theta$ off the branch cut. Complexity $O(n^{3})$.

\section{Discussion}

Uniqueness is \emph{soft}: it needs only that both summands of $S$ are nonnegative and strictly increasing, with no numerical input. Localization is \emph{hard}: the true margins are $3.4\%$ below $1$ at $t=6/5$ and $2.4\%$ above at $t=5/4$, so every inequality must be sharp to about three decimals.

The device making the hard part tractable deserves isolation. Both $\log$ and $\arctan$ have excellent elementary two-sided rational bounds near their distinguished points --- $\log$ near $x=1$ via tangent lines, $\arctan$ near $y=0$ with a gap $O(y^{3})$ --- and degrade badly away from them. In both cases a \emph{reduction identity} transports the evaluation point back into the good region at the price of a known constant:
\[
\log(2u)=\log2+\log u,\qquad \arctan\frac{1+y}{1-y}=\frac{\pi}{4}+\arctan y .
\]
These are exactly the classical devices behind fast computation of $\log$ and of $\pi$; the arctangent identity is the mechanism of Machin's formula.

Limitations: the certified interval, while narrow, is not sharp ($t^{\star}=1.22904\ldots$); Theorem~\ref{thm:expsurj} assumes finite spectrum; and the determinant--trace correspondence $\det\exp(A)=\exp(\tr A)$, which would give $\exp(iH)\in SU(n)\iff\tr H\in2\pi\ZZ$, is not proved here.

\section{Future work}

\begin{enumerate}
\item \textbf{Sharper enclosures.} Prove $t^{\star}\in[1.229,1.2291]$ by the same method with higher-precision certified bounds on $\log2$ and $\pi$ and finer rational factorizations of $1+t^{2}$.
\item \textbf{Transcendence.} Conjecturally $t^{\star}$ is transcendental; a proof would presumably need a Schanuel-type input. Even irrationality appears open.
\item \textbf{Determinant--trace bridge.} Prove $\det\exp(A)=\exp(\tr A)$ and deduce the exact trace congruence class characterising $\exp(iH)\in SU(n)$.
\item \textbf{Beyond finite spectrum.} Extend Theorem~\ref{thm:expsurj} to unitaries whose spectrum omits a point (immediate) and then to arbitrary unitaries via spectral measures.
\item \textbf{Operator analogues.} Replace $1+ti$ by $1+tN$ for normal or nilpotent $N$ and study $\|\Log(1+tN)\|=1$ in operator norm.
\item \textbf{The full arc.} Characterise $\{\pu(\Log(1+ti)):t>0\}$ as an explicit subarc of the unit circle.
\end{enumerate}

